import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.NetworkChunkPublisherUpdate{Position: protocol.BlockPos{1, -2, 3}, Radius: 160,
#   SavedChunks: []protocol.ChunkPos{{0, 0}, {-1, 5}}}
WITH_SAVED_CHUNKS = bytes.fromhex("020306a001020000000000010a")

# generated by gophertunnel b8bd735:
# &packet.NetworkChunkPublisherUpdate{Position: protocol.BlockPos{0, 0, 0}, Radius: 0}
EMPTY = bytes.fromhex("0000000000000000")

GOLDENS = [
    pytest.param(
        v2225.NetworkChunkPublisherUpdatePacket(
            position=v2225.BlockPos(x=1, y=-2, z=3),
            radius=160,
            server_built_chunks=[v2225.ChunkPos(x=0, z=0), v2225.ChunkPos(x=-1, z=5)],
        ),
        WITH_SAVED_CHUNKS,
        id="with-saved-chunks",
    ),
    pytest.param(
        v2225.NetworkChunkPublisherUpdatePacket(position=v2225.BlockPos(x=0, y=0, z=0), radius=0),
        EMPTY,
        id="empty",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_network_chunk_publisher_update_is_packet_121(version):
    assert version.PACKETS[121] is version.NetworkChunkPublisherUpdatePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_network_chunk_publisher_update_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_network_chunk_publisher_update_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_an_empty_server_built_chunk_list_still_writes_a_four_byte_count():
    assert len(EMPTY) == 8
    with pytest.raises(ValueError, match="at byte"):
        v2225.NetworkChunkPublisherUpdatePacket.from_bytes(EMPTY[:5])
